import { createSequence, addStep } from '@projexlight/sdk-sequence';

const seq = await createSequence({ tenant_id, name: 'Trial Nurture', sequence_type: 'nurture' });
await addStep({ tenant_id, sequence_id: seq.sequence_id, step_number: 1, channel: 'email', action: 'send', schedule_mode: 'immediate' });
await addStep({ tenant_id, sequence_id: seq.sequence_id, step_number: 2, channel: 'email', action: 'send', schedule_mode: 'delay', delay_seconds: 259200 });

import { enroll } from '@projexlight/sdk-sequence';

const result = await enroll({ tenant_id, sequence_id: seq.sequence_id, subject_persona_id, event_type: 'form_submit' });
if (result.already_enrolled) {
  console.log('persona already running this sequence, no-op');
}

import { runSequenceTick } from '@projexlight/sdk-sequence';

const tick = await runSequenceTick(50);
console.log(`claimed ${tick.claimed}, sent ${tick.sent}, deferred ${tick.deferred}`);

import { checkFrequencyGuards, recordChannelOutcome } from '@projexlight/sdk-sequence';

const decision = await checkFrequencyGuards({ tenant_id, subject_persona_id, channel: 'email', dedupe_hash });
if (decision.decision === 'block') return; // e.g. cooldown / max_messages / circuit_open
await recordChannelOutcome(tenant_id, 'email', true);
